import Modal from "../../002 01-starting-project/01-starting-project/src/components/UI/Modal";
import "./Cart.css";
import React,{Fragment, useState} from 'react';

const Cart=({items})=>{
       const [openCart, setOpenCart]=useState(false);
       const totalQuantity = items.reduce((acc, item) => acc + item.amount, 0);
       const totalPrice = items.reduce((acc, item) => acc + item.amount * item.price, 0);

       const handleCart=()=>{
        setOpenCart(true);
       }

       const closeCartHandling=()=>{
        setOpenCart(false);
       }
    return(
        <Fragment>
        <div className="cart">
            <label>items</label>
            <span>{totalQuantity}</span>  
            <div className="button-div">
                <button className="cart-button" onClick={handleCart}>Open Cart</button>
            </div>
        </div>    
           {openCart && (
            <Modal>
            <ul>
        
        {items.map((item) => (
          <li className="cartproduct" key={index}>
             <span >X{item.amount}</span> 
            <span >{item.name}</span> 
           
            <span>Rs{item.price}/item</span>
          </li>
        ))}
      </ul>
      <div className="total">
            <span>Total Amount</span>
            <span>₹ {totalPrice}</span>
          </div>
      <div className="actions">
            <button
              className="button--alt"
              onClick={closeCartHandling}
            >
              Close
            </button>
            <button className="button">Order</button>
          </div>
            </Modal>
            )} 
        </Fragment>
       

      
    )
}
export default Cart;
